import {resourceByPath,resourceTrail,servicesRoot,materialsRoot,materialLeaves,filterMaterials,resourcePhoto,resolveServiceIds,materialFacetDefinitions,getMaterialFacets,getMaterialFilterConflict,resourceMediaForNode} from './resource-catalog.mjs';

import {catalogDirectory,categoryPreview} from './catalog-directory.mjs';

export function createResourceUI({esc,btn,crumb,field}){
 const shorten=v=>String(v||'').length>160?String(v).slice(0,157).replace(/\s+\S*$/,'')+'…':String(v||'');
 const noun=n=>n.isLeaf?(n.kind==='material'?'Выбрать материал':'Подробнее об обработке'):`${n.children.length} ${n.children.length===1?'вариант':'вариантов'} для выбора`;
 function card(n,index=0){const media=resourceMediaForNode(n);return `<a class="choice-card resource-choice-card" href="${n.url}" data-resource-path="${n.path}"><div class="choice-photo">${resourcePhoto(n)}<span class="choice-number">${String(index+1).padStart(2,'0')}</span></div><div class="choice-copy"><h3>${esc(n.title)}</h3><p>${esc(shorten(n.intro))}</p>${media.limitation?`<p class="resource-media-caption">${esc(media.limitation)}</p>`:''}${categoryPreview(n,esc)}<div class="choice-bottom"><span>${noun(n)}</span><span class="choice-arrow">→</span></div></div></a>`;}
 function grid(nodes){
  if(!nodes.length)return `<div class="empty"><h3>Такого сочетания пока нет</h3><p>Измените фильтры или опишите нужный материал.</p>${btn('Сбросить фильтры','#/materials','clear')}</div>`;
  return `<div class="choice-grid ${nodes.length===2?'two-choices':''}">${nodes.map((n,i)=>card(n,i)).join('')}</div>`;
 }
 function trail(n){return crumb(resourceTrail(n).map(x=>[x.title,x.path===n.path?null:x.url]));}
 function back(n){const parent=resourceByPath.get(n.parentPath);return `<nav class="selection-toolbar" aria-label="Вернуться к разделу"><a class="selection-back" href="${parent?.url||'#/'}">← ${esc(parent?.title||'На главную')}</a><a class="selection-map" href="${n.kind==='material'?'#/production':'#/materials'}">${n.kind==='material'?'Услуги производства':'Каталог материалов'} ↗</a></nav>`;}
 function portal(title,text,node,label){return `<a class="resource-portal" href="${node.url}"><div>${resourcePhoto(node)}</div><section><span class="eyebrow">${esc(label)}</span><h2>${title}</h2><p>${text}</p><span class="portal-action">Открыть каталог <span>↗</span></span></section></a>`;}
 function homeEntries(){return `<section class="section resource-home"><div class="section-top"><div><div class="eyebrow">ВОЗМОЖНОСТИ МАТЕРИАЛА</div><h2>Выберите стекло.<br><em>Задайте ему форму.</em></h2></div><p>Материалы, обработка и готовые конструкции — три способа начать ваш проект.</p></div><div class="resource-home-grid">${portal('Производство','Резка, кромка, отверстия, триплекс и декоративная обработка — отдельные услуги и варианты.',servicesRoot,'УСЛУГИ ОБРАБОТКИ')}${portal('Материалы','Прозрачность, оттенок, отражение и фактура. Полная коллекция стекла и зеркал.',materialsRoot,'КАТАЛОГ МАТЕРИАЛОВ')}</div></section>`;}
 function productionHome(){return `${trail(servicesRoot)}<section class="manufacturing-hero"><div><div class="eyebrow">VIP GLASS / ПРОИЗВОДСТВО</div><h1>От листа стекла<br><em>до вашей детали.</em></h1><p>Выберите операцию, материал и результат, который нужен вашему проекту. Изготовление по размерам, эскизам и чертежам.</p><div class="button-row"><a href="#production-services" data-scroll="production-services" class="btn primary">Выбрать услугу <span>↓</span></a>${btn('Каталог материалов','#/materials','clear')}</div></div><figure>${resourcePhoto('production-workbench',{eager:true})}<figcaption>Визуализация процессов и материалов</figcaption></figure></section><section class="selection-page" id="production-services"><div class="section-top"><div><div class="eyebrow">ВЫБЕРИТЕ ЗАДАЧУ</div><h2>Что нужно<br><em>сделать со стеклом?</em></h2></div><p>Каждый процесс — отдельный раздел. Выберите операцию, затем её вид, обработку и точные параметры.</p></div>${catalogDirectory(servicesRoot.children,{esc,photo:n=>resourcePhoto(n),card,attribute:'data-resource-path'})}<div class="production-material-entry">${portal('Материалы для вашего проекта','Crystal Vision, тонированное, матовое, рифлёное, окрашенное стекло, зеркала и многослойные составы.',materialsRoot,'ПОДРАЗДЕЛ ПРОИЗВОДСТВА')}</div><section class="production-how"><div class="section-top"><h2>Понятное задание.<br><em>Точный результат.</em></h2></div><div class="process"><article><span class="step-number">01</span><h3>Материал</h3><p>Прозрачность, цвет, фактура и назначение детали.</p></article><article><span class="step-number">02</span><h3>Геометрия</h3><p>Размеры, контур, отверстия и вырезы по вашему заданию.</p></article><article><span class="step-number">03</span><h3>Обработка</h3><p>Кромка, состав, поверхность и последовательность операций.</p></article><article><span class="step-number">04</span><h3>Комплект</h3><p>Количество, маркировка и состав деталей для вашего проекта.</p></article></div></section><div class="selection-footer"><p>Можно начать с готового чертежа или описания задачи.</p>${btn('Подготовить задание','#/production/request')}</div></section>`;}
 function materialSelect(definition,entries){return `<label>${esc(definition.label)}<select name="${definition.key}" aria-describedby="materials-filter-help">${entries.map(entry=>`<option value="${esc(entry.value)}" data-count="${entry.count}" ${entry.selected?'selected':''} ${entry.disabled?'disabled':''}>${esc(entry.label)}${entry.value?` · ${entry.count}${entry.selected&&!entry.available?' — нет сочетания':''}`:''}</option>`).join('')}</select></label>`;}
 const materialFilterURL=params=>'#/materials'+(params.toString()?'?'+params.toString():'');
 function materialEmpty(params,conflict){
  if(conflict)return `<div class="empty material-filter-conflict" role="status"><h2>Выбранные свойства не сочетаются</h2><p>${esc(conflict.reason)}</p><p>Условия из ссылки сохранены. Можно убрать конфликтующие свойства: ${esc(conflict.removed.map(f=>`${f.label} — ${f.value}`).join('; '))}.</p>${btn('Сбросить конфликтующие свойства',materialFilterURL(conflict.recovery),'primary')}${btn('Все материалы','#/materials','clear')}</div>`;
  const withoutQuery=new URLSearchParams(params);withoutQuery.delete('q');
  return `<div class="empty material-search-empty" role="status"><h2>По запросу ничего не найдено</h2><p>В выбранных материалах нет совпадений с «${esc(params.get('q')||'')}». Попробуйте другое название или уберите поисковый запрос.</p>${btn('Убрать поисковый запрос',materialFilterURL(withoutQuery),'primary')}${btn('Все материалы','#/materials','clear')}</div>`;
 }
 function materialsPage(params=new URLSearchParams()){
  const active=['family','transparency','color','q'].some(k=>params.get(k)),list=active?filterMaterials(params):materialsRoot.children;
  const facets=getMaterialFacets(params),conflict=getMaterialFilterConflict(params);
  const results=active?(list.length?grid(list,materialsRoot,{allPhotos:true}):materialEmpty(params,conflict)):catalogDirectory(materialsRoot.children,{esc,photo:n=>resourcePhoto(n),card,attribute:'data-resource-path'});
  return `${trail(materialsRoot)}<section class="selection-page"><nav class="selection-toolbar"><a class="selection-back" href="#/production">← Производство</a><a class="selection-map" href="#/catalog">Готовые конструкции ↗</a></nav><header class="selection-heading"><div class="eyebrow">VIP GLASS / МАТЕРИАЛЫ</div><h1>Прозрачность. Цвет.<br><em>Характер поверхности.</em></h1><p>Выберите семейство материала или найдите нужное сочетание через фильтры. Прозрачная бесцветная основа — Crystal Vision.</p></header><form class="resource-filter-form" id="materials-filter-form">${materialFacetDefinitions.map(definition=>materialSelect(definition,facets[definition.key])).join('')}<label>Поиск<input type="search" name="q" placeholder="Например, рифлёное" value="${esc(params.get('q')||'')}"></label><button class="btn primary" type="submit">Показать <span>→</span></button><a class="filter-clear" href="#/materials">Сбросить</a></form><p class="form-note" id="materials-filter-help">Числа у семейств показывают их полный состав, у свойств — подходящие сочетания. При смене семейства несовместимые свойства сбросятся. Поиск уточняет выдачу.</p><div class="resource-result-count" aria-live="polite">${active?`${list.length} вариантов по вашему выбору`:`${materialsRoot.children.length} семейств · ${materialLeaves.length} вариантов материала`}</div>${results}<div class="material-guidance"><h2>Материал и обработка<br><em>работают вместе.</em></h2><p>Триплекс может быть прозрачным, матовым или декоративным. Закалка, форма и кромка задаются отдельно. В карточках собраны связанные варианты и операции.</p>${btn('Выбрать обработку','#/production','clear')}</div></section>`;
 }
 function requestForm(node,params=new URLSearchParams()){
  const title=node?.title||params.get('title')||'',materialId=params.get('material')||'',material=resourceByPath.get(materialId);
  return `<form id="resource-form" class="config-form resource-order" data-resource="${node?.path||''}"><div class="eyebrow">ДОБАВИТЬ В ОБЩЕЕ ЗАДАНИЕ</div><div class="form-grid"><div class="field full"><label for="resource-title">Название детали или задачи</label><input id="resource-title" name="title" required value="${esc(title)}" placeholder="Например, комплект стекла для перегородки"></div>${field('Ширина, мм','resource-width','','number','min="1" step="any" placeholder="Уточним по чертежу"')}${field('Высота / длина, мм','resource-height','','number','min="1" step="any" placeholder="Уточним по чертежу"')}${field('Количество, шт.','resource-quantity',1,'number','min="1" step="1" required')}${field('Толщина / состав','resource-thickness','','text','placeholder="Если уже определены"')}${node?.properties?.bevelWidth?field('Ширина фацета, мм','resource-bevel-width',parseFloat(node.properties.bevelWidth)||'','number',`min="0.1" step="any" ${parseFloat(node.properties.bevelWidth)?'readonly':'required placeholder="Укажите точную ширину"'}`):''}<div class="field full"><label for="resource-material">${node?.kind==='material'?'Выбранный материал':'Материал для обработки'}</label>${node?.kind==='material'?`<input id="resource-material" readonly value="${esc(node.title)}"><input type="hidden" name="resource-material" value="${esc(node.path)}">`:`<select id="resource-material" name="resource-material"><option value="">Нужен подбор по задаче</option>${materialLeaves.map(m=>`<option value="${m.path}" ${m.path===(node?.kind==='material'?node.path:material?.path)?'selected':''}>${esc(m.title)}</option>`).join('')}</select>`}</div>${(!node||node.kind==='service'&&!['lamination','bonding','production-films'].includes(node.family))?'<p class="form-note field full">Если нужен закалённый материал, резку, отверстия и механическую обработку кромки выполняем до закалки. Готовые закалённые детали не подрезаем и не пересверливаем.</p>':''}<div class="field full"><label for="resource-note">Детали задания</label><textarea id="resource-note" name="note" placeholder="Контур, обработка, назначение, особенности и пожелания…"></textarea></div></div><button type="submit" class="btn primary">Добавить в мой проект <span>+</span></button><div id="resource-added" class="added-confirmation" hidden><span>Задание добавлено.</span><a href="#/project">Открыть проект →</a></div><p class="form-note">Размеры можно уточнить позже. Чертежи и фотографии приложите в «Моём проекте».</p></form>`;
 }
 function requestPage(params){return `${crumb([['Производство','#/production'],['Задание по чертежу']])}<section class="selection-page resource-request"><a class="selection-back" href="#/production">← Услуги производства</a><header class="selection-heading"><div class="eyebrow">ПРОИЗВОДСТВО ПО ВАШЕМУ ТЗ</div><h1>Расскажите,<br><em>что изготовить.</em></h1><p>Соберите размеры, выбранный материал и операции в одном задании.</p></header>${requestForm(null,params)}</section>`;}
 function related(node){const ids=node.kind==='service'?node.materialIds:node.serviceIds,root=node.kind==='service'?materialsRoot:servicesRoot;const nodes=node.kind==='service'?(ids||[]).map(id=>root.children.find(n=>n.id===id)).filter(Boolean):resolveServiceIds(ids);if(!nodes.length)return '';return `<section class="resource-related"><div class="section-top"><h2>${node.kind==='service'?'Материалы для этой задачи':'Операции при изготовлении'}</h2><a class="selection-map" href="${root.url}">Весь каталог ↗</a></div><div class="directory-subtypes related-processes">${nodes.map((n,i)=>card(n,i)).join('')}</div></section>`;}
 function leaf(node){const media=resourceMediaForNode(node);const label={transparency:'Прозрачность',finish:'Поверхность',color:'Цвет',structure:'Структура',base:'Основа',selection:'Подбор',bevelWidth:'Ширина фацета',bevelGeometry:'Линия фацета'};return `${trail(node)}<section class="selection-page selected-product resource-detail">${back(node)}<div class="leaf-layout"><div class="leaf-visual"><figure class="product-gallery"><button type="button" class="gallery-open" data-resource-src="${esc(media.src)}" data-resource-alt="${esc(media.alt)}" data-caption="${esc(media.caption)}">${resourcePhoto(node,{eager:true})}<span class="gallery-expand">↗</span></button><p>${esc(media.caption)}</p><figcaption><span>${esc(node.title)}</span><span>Увеличить ↗</span></figcaption></figure></div><div class="leaf-details"><span class="eyebrow">${node.kind==='material'?'МАТЕРИАЛ ДЛЯ ВАШЕГО ПРОЕКТА':'ПРОИЗВОДСТВЕННАЯ УСЛУГА'}</span><h1>${esc(node.title)}</h1><p>${esc(node.intro)}</p>${node.result?`<div class="resource-result"><span class="eyebrow">${node.kind==='material'?'ХАРАКТЕР МАТЕРИАЛА':'РЕЗУЛЬТАТ'}</span><p>${esc(node.result)}</p></div>`:''}${node.properties?`<dl class="selected-specs">${Object.entries(node.properties).map(([key,value])=>`<div><dt>${esc(label[key]||key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`:''}${requestForm(node)}</div></div><div class="resource-specification"><section><h2>Что поможет<br><em>подготовить расчёт.</em></h2><ul>${(node.brief||['Размеры и количество','Назначение детали','Эскиз или чертёж']).map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section>${node.notes?.length?`<section><h2>Детали выбора</h2>${node.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</section>`:''}</div>${related(node)}</section>`;}
 function branch(node){return `${trail(node)}<section class="selection-page">${back(node)}<header class="selection-heading"><div class="eyebrow">${node.kind==='material'?'КОЛЛЕКЦИЯ МАТЕРИАЛОВ':'ПРОИЗВОДСТВО / ВЫБОР ОПЕРАЦИИ'}</div><h1>${esc(node.title)}</h1><p>${esc(node.intro)}</p></header>${node.children.some(n=>!n.isLeaf)?catalogDirectory(node.children,{esc,photo:n=>resourcePhoto(n),card,attribute:'data-resource-path'}):grid(node.children,node)}${related(node)}<div class="selection-footer"><p>Есть нестандартная задача или готовый чертёж?</p>${btn('Подготовить задание','#/production/request','clear')}</div></section>`;}
 function page(node,params){if(node.path==='/production')return productionHome();if(node.path==='/materials')return materialsPage(params);return node.isLeaf?leaf(node):branch(node);}
 return {page,requestPage,homeEntries,card,grid};
}
